#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <vector>
#include <string>
#include "lodepng.h"
#include "cJSON.h"

static char* read_file(const char* path){
    FILE* f=fopen(path,"rb");
    if(!f){fprintf(stderr,"cannot open %s\n",path);exit(1);}
    fseek(f,0,SEEK_END);long n=ftell(f);fseek(f,0,SEEK_SET);
    char* buf=(char*)malloc(n+1);
    if(fread(buf,1,n,f)!=(size_t)n){fprintf(stderr,"read err\n");exit(1);}
    buf[n]=0;fclose(f);return buf;
}

static std::vector<std::vector<double>> mat(cJSON* root,const char* key){
    cJSON* a=cJSON_GetObjectItemCaseSensitive(root,key);
    std::vector<std::vector<double>> m;
    cJSON* row;
    cJSON_ArrayForEach(row,a){
        std::vector<double> r;cJSON* v;
        cJSON_ArrayForEach(v,row) r.push_back(v->valuedouble);
        m.push_back(r);
    }
    return m;
}
static std::vector<double> vec(cJSON* root,const char* key){
    cJSON* a=cJSON_GetObjectItemCaseSensitive(root,key);
    std::vector<double> r;cJSON* v;
    cJSON_ArrayForEach(v,a) r.push_back(v->valuedouble);
    return r;
}

// linear: out = W x + b, W is [out][in]
static std::vector<double> linear(const std::vector<std::vector<double>>& W,
                                  const std::vector<double>& b,
                                  const std::vector<double>& x){
    std::vector<double> o(W.size());
    for(size_t i=0;i<W.size();++i){
        double s=b[i];
        for(size_t j=0;j<x.size();++j) s+=W[i][j]*x[j];
        o[i]=s;
    }
    return o;
}
static void relu(std::vector<double>& v){for(auto&x:v) if(x<0) x=0;}

int main(int argc,char** argv){
    if(argc<3){fprintf(stderr,"usage: %s weights.json image.png\n",argv[0]);return 1;}
    // load weights
    char* txt=read_file(argv[1]);
    cJSON* root=cJSON_Parse(txt);
    if(!root){fprintf(stderr,"json parse error\n");return 1;}
    auto iw=mat(root,"input_layer.weight");  auto ib=vec(root,"input_layer.bias");
    auto hw=mat(root,"hidden_layer.weight"); auto hb=vec(root,"hidden_layer.bias");
    auto ow=mat(root,"output_layer.weight"); auto ob=vec(root,"output_layer.bias");

    // load image as grayscale
    std::vector<unsigned char> img;unsigned w,h;
    unsigned err=lodepng::decode(img,w,h,argv[2],LCT_GREY,8);
    if(err){fprintf(stderr,"png decode error: %s\n",lodepng_error_text(err));return 1;}
    // resize to 28x28 if needed (nearest)
    const int W=28,H=28;
    std::vector<double> x(W*H);
    const double mean=0.1307, std=0.3081;
    for(int yy=0;yy<H;++yy)for(int xx=0;xx<W;++xx){
        int sy=(int)((long)yy*h/H), sx=(int)((long)xx*w/W);
        unsigned char p=img[(size_t)sy*w+sx];
        x[yy*W+xx]=((double)p/255.0 - mean)/std;
    }
    auto a=linear(iw,ib,x); relu(a);
    auto b2=linear(hw,hb,a); relu(b2);
    auto o=linear(ow,ob,b2);
    int best=0;for(size_t i=1;i<o.size();++i) if(o[i]>o[best]) best=i;
    printf("%d\n",best);
    cJSON_Delete(root);free(txt);
    return 0;
}
